    Bug 2054833 - Mail URL destructors must release nsWeakPtr members via NS_ReleaseOnMainThread. r=babolivier

    Differential Revision: https://phabricator.services.mozilla.com/D312015

diff --git a/mailnews/base/src/nsMsgMailNewsUrl.cpp b/mailnews/base/src/nsMsgMailNewsUrl.cpp
index 6dea55e9644..f4a95966027 100644
--- a/mailnews/base/src/nsMsgMailNewsUrl.cpp
+++ b/mailnews/base/src/nsMsgMailNewsUrl.cpp
@@ -59,6 +59,13 @@ nsMsgMailNewsUrl::~nsMsgMailNewsUrl() {
   NS_ReleaseOnMainThread("nsMsgMailNewsUrl::m_searchSession",
                          m_searchSession.forget());

+  // Weak references hold a non-threadsafe nsWeakReference proxy that is created
+  // on and belongs to the main thread, so it must be released there too.
+  NS_ReleaseOnMainThread("nsMsgMailNewsUrl::m_msgWindowWeak",
+                         m_msgWindowWeak.forget());
+  NS_ReleaseOnMainThread("nsMsgMailNewsUrl::m_loadGroupWeak",
+                         m_loadGroupWeak.forget());
+
   nsTObserverArray<nsCOMPtr<nsIUrlListener>>::ForwardIterator iter(
       mUrlListeners);
   while (iter.HasMore()) {
diff --git a/mailnews/imap/src/nsImapUrl.cpp b/mailnews/imap/src/nsImapUrl.cpp
index 0a83ffb9421..16f37544347 100644
--- a/mailnews/imap/src/nsImapUrl.cpp
+++ b/mailnews/imap/src/nsImapUrl.cpp
@@ -11,6 +11,7 @@
 #include "plstr.h"
 #include "prprf.h"
 #include "nsCOMPtr.h"
+#include "nsProxyRelease.h"
 #include "nsImapUtils.h"
 #include "nsIImapMockChannel.h"
 #include "nsIImapMailFolderSink.h"
@@ -67,6 +68,20 @@ nsImapUrl::~nsImapUrl() {
   PR_FREEIF(m_destinationCanonicalFolderPathSubString);
   PR_FREEIF(m_sourceCanonicalFolderPathSubString);
   PR_FREEIF(m_searchCriteriaString);
+
+  // This URL can be created and destroyed on the imap thread (or, via
+  // principal/URI deserialization, on other threads). The weak references
+  // hold a non-threadsafe nsWeakReference proxy that belongs to the main
+  // thread, so it must be released there too.
+  NS_ReleaseOnMainThread("nsImapUrl::m_imapFolder", m_imapFolder.forget());
+  NS_ReleaseOnMainThread("nsImapUrl::m_imapMailFolderSink",
+                         m_imapMailFolderSink.forget());
+  NS_ReleaseOnMainThread("nsImapUrl::m_imapMessageSink",
+                         m_imapMessageSink.forget());
+  NS_ReleaseOnMainThread("nsImapUrl::m_imapServerSink",
+                         m_imapServerSink.forget());
+  NS_ReleaseOnMainThread("nsImapUrl::m_channelWeakPtr",
+                         m_channelWeakPtr.forget());
 }

 NS_IMPL_ADDREF_INHERITED(nsImapUrl, nsMsgMailNewsUrl)
